#include <string>
#include <mutex>
#include <shared_mutex>
#include <unordered_map>
#include <chrono>
#include <atomic>
#include <functional>
#include <memory>
#include <vector>
#include <openssl/hmac.h>
#include <openssl/evp.h>

namespace db_driver {

struct AuthToken {
    std::string service_id;
    std::string session_key;
    uint64_t issued_at;
    uint64_t expires_at;
    uint32_t privilege_level;
};

class TokenCache {
private:
    mutable std::shared_mutex cache_mutex_;
    std::unordered_map<std::string, AuthToken> tokens_;

public:
    bool lookup(const std::string& service_id, AuthToken& out) const {
        std::shared_lock lock(cache_mutex_);
        auto it = tokens_.find(service_id);
        if (it != tokens_.end()) {
            out = it->second;
            return true;
        }
        return false;
    }

    void store(const std::string& service_id, const AuthToken& token) {
        std::unique_lock lock(cache_mutex_);
        tokens_[service_id] = token;
    }

    void invalidate(const std::string& service_id) {
        std::unique_lock lock(cache_mutex_);
        tokens_.erase(service_id);
    }
};

class AuthVerifier {
private:
    std::string shared_secret_;
    TokenCache& cache_;
    std::atomic<uint64_t> nonce_counter_{0};

    // Tracks pending authentication requests to prevent replay
    mutable std::mutex pending_mutex_;
    std::unordered_map<std::string, uint64_t> pending_auths_;

    std::string compute_hmac(const std::string& data) const {
        unsigned char result[EVP_MAX_MD_SIZE];
        unsigned int len = 0;
        HMAC(EVP_sha256(), shared_secret_.data(), shared_secret_.size(),
             reinterpret_cast<const unsigned char*>(data.data()), data.size(),
             result, &len);
        return std::string(reinterpret_cast<char*>(result), len);
    }

    uint64_t current_time_ms() const {
        return std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();
    }

public:
    AuthVerifier(const std::string& secret, TokenCache& cache)
        : shared_secret_(secret), cache_(cache) {}

    // Phase 1: Generate challenge for cross-service auth
    std::string generate_challenge(const std::string& service_id) {
        uint64_t nonce = nonce_counter_.fetch_add(1, std::memory_order_relaxed);
        uint64_t timestamp = current_time_ms();

        std::string challenge = service_id + ":" + 
                               std::to_string(nonce) + ":" +
                               std::to_string(timestamp);

        // Register pending auth - store timestamp for expiry check
        {
            std::lock_guard<std::mutex> lock(pending_mutex_);
            pending_auths_[service_id] = timestamp;
        }

        return challenge;
    }

    // Phase 2: Verify response and issue token
    // Returns true if authentication succeeds
    bool verify_and_issue(const std::string& service_id,
                          const std::string& challenge,
                          const std::string& response,
                          uint32_t requested_privilege) {

        // Check if there's a pending auth for this service
        uint64_t auth_timestamp;
        {
            std::lock_guard<std::mutex> lock(pending_mutex_);
            auto it = pending_auths_.find(service_id);
            if (it == pending_auths_.end()) {
                return false;
            }
            auth_timestamp = it->second;
            // Remove from pending - consumed
            pending_auths_.erase(it);
        }
        // <- Window: pending auth consumed, but token not yet issued

        // Verify timing - challenge must be recent (5 second window)
        uint64_t now = current_time_ms();
        if (now - auth_timestamp > 5000) {
            return false;
        }

        // Verify HMAC response
        std::string expected = compute_hmac(challenge + ":" + shared_secret_);
        if (response.size() != expected.size()) {
            return false;
        }

        // Constant-time comparison
        volatile unsigned char diff = 0;
        for (size_t i = 0; i < expected.size(); ++i) {
            diff |= static_cast<unsigned char>(response[i]) ^ 
                    static_cast<unsigned char>(expected[i]);
        }

        if (diff != 0) {
            return false;
        }

        // Issue token with requested privileges
        AuthToken token;
        token.service_id = service_id;
        token.session_key = compute_hmac(service_id + ":" + std::to_string(now));
        token.issued_at = now;
        token.expires_at = now + 3600000; // 1 hour
        token.privilege_level = requested_privilege;

        cache_.store(service_id, token);
        return true;
    }
};

class DatabaseConnection {
private:
    TokenCache token_cache_;
    std::unique_ptr<AuthVerifier> verifier_;

    bool check_privilege(const std::string& service_id, uint32_t required_level) {
        AuthToken token;
        if (!token_cache_.lookup(service_id, token)) {
            return false;
        }

        uint64_t now = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();

        if (now > token.expires_at) {
            token_cache_.invalidate(service_id);
            return false;
        }

        return token.privilege_level >= required_level;
    }

public:
    DatabaseConnection(const std::string& secret) 
        : verifier_(std::make_unique<AuthVerifier>(secret, token_cache_)) {}

    // Initiate cross-service authentication
    std::string begin_auth(const std::string& service_id) {
        return verifier_->generate_challenge(service_id);
    }

    // Complete authentication with challenge-response
    bool complete_auth(const std::string& service_id,
                      const std::string& challenge,
                      const std::string& response,
                      uint32_t privilege) {
        return verifier_->verify_and_issue(service_id, challenge, response, privilege);
    }

    // Execute query if authorized
    bool execute_query(const std::string& service_id, 
                      const std::string& query,
                      uint32_t required_privilege) {
        if (!check_privilege(service_id, required_privilege)) {
            return false;
        }
        // Execute query...
        return true;
    }
};

} // namespace db_driver
